  // Control 2 Register
  struct Ctrl2Fields {
    enum class eEDFLTDIS : std::uint32_t {
      // Edge filter is enabled
      eENABLE = 0,
      // Edge filter is disabled
      eDISABLE = 1,
    };

    enum class eISOCANFDEN : std::uint32_t {
      // FlexCAN operates using the non-ISO CAN FD protocol.
      enon_ISO = 0,
      // FlexCAN operates using the ISO CAN FD protocol (ISO 11898-1).
      eISO = 1,
    };

    enum class ePREXCEN : std::uint32_t {
      // Protocol exception is disabled.
      eDISABLE = 0,
      // Protocol exception is enabled.
      eENABLE = 1,
    };

    enum class eTIMER_SRC : std::uint32_t {
      // The free running timer is clocked by the CAN bit clock, which defines the baud rate on the CAN bus.
      eCAN_bit_clock = 0,
      // The free running timer is clocked by an external time tick. The period can be either adjusted to be equal to the baud rate on the CAN bus, or a different value as required. See the device-specific section for details about the external time tick.
      eexternal_clock = 1,
    };

    enum class eEACEN : std::uint32_t {
      // Rx mailbox filter's IDE bit is always compared and RTR is never compared despite mask bits.
      eRTR_compare_no = 0,
      // Enables the comparison of both Rx mailbox filter's IDE and RTR bit with their corresponding bits within the incoming frame. Mask bits do apply.
      eRTR_compare_yes = 1,
    };

    enum class eRRS : std::uint32_t {
      // Remote response frame is generated.
      eremote_response_frame_not_generated = 0,
      // Remote request frame is stored.
      eremote_response_frame_generated = 1,
    };

    enum class eMRP : std::uint32_t {
      // Matching starts from Rx FIFO and continues on mailboxes.
      eid2 = 0,
      // Matching starts from mailboxes and continues on Rx FIFO.
      eid4 = 1,
    };

    enum class eWRMFRZ : std::uint32_t {
      // Maintain the write access restrictions.
      eDISABLE = 0,
      // Enable unrestricted write access to FlexCAN memory.
      eENABLE = 1,
    };

    enum class eECRWRE : std::uint32_t {
      // Disable update.
      eDISABLE = 0,
      // Enable update.
      eENABLE = 1,
    };

    enum class eBOFFDONEMSK : std::uint32_t {
      // Bus off done interrupt disabled.
      eDISABLE = 0,
      // Bus off done interrupt enabled.
      eENABLE = 1,
    };

    enum class eERRMSK_FAST : std::uint32_t {
      // ERRINT_FAST error interrupt disabled.
      eDISABLE = 0,
      // ERRINT_FAST error interrupt enabled.
      eENABLE = 1,
    };

    // Edge Filter Disable
    using EDFLTDIS = ftl::mmio::Field<1, 11, eEDFLTDIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // ISO CAN FD Enable
    using ISOCANFDEN = ftl::mmio::Field<1, 12, eISOCANFDEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Protocol Exception Enable
    using PREXCEN = ftl::mmio::Field<1, 14, ePREXCEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Timer Source
    using TIMER_SRC = ftl::mmio::Field<1, 15, eTIMER_SRC, ftl::mmio::RW, ftl::mmio::Normal>;
    // Entire Frame Arbitration Field Comparison Enable For Rx Mailboxes
    using EACEN = ftl::mmio::Field<1, 16, eEACEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Remote Request Storing
    using RRS = ftl::mmio::Field<1, 17, eRRS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Mailboxes Reception Priority
    using MRP = ftl::mmio::Field<1, 18, eMRP, ftl::mmio::RW, ftl::mmio::Normal>;
    // Tx Arbitration Start Delay
    using TASD = ftl::mmio::Field<5, 19, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Number Of Rx FIFO Filters
    using RFFN = ftl::mmio::Field<4, 24, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Write-Access To Memory In Freeze Mode
    using WRMFRZ = ftl::mmio::Field<1, 28, eWRMFRZ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Error-correction Configuration Register Write Enable
    using ECRWRE = ftl::mmio::Field<1, 29, eECRWRE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Bus Off Done Interrupt Mask
    using BOFFDONEMSK = ftl::mmio::Field<1, 30, eBOFFDONEMSK, ftl::mmio::RW, ftl::mmio::Normal>;
    // Error Interrupt Mask for errors detected in the data phase of fast CAN FD frames
    using ERRMSK_FAST = ftl::mmio::Field<1, 31, eERRMSK_FAST, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct Ctrl2Fields

